(function (global) {
  "use strict";

  const NOISE_TAGS = new Set([
    "script",
    "style",
    "noscript",
    "iframe",
    "object",
    "embed",
    "header",
    "footer",
    "nav",
    "aside",
    "form",
    "button",
    "select",
    "option",
    "textarea",
    "figure",
    "figcaption",
    "svg",
    "canvas",
    "video",
    "audio",
    "picture",
  ]);

  const NOISE_PATTERN =
    /comment|meta|footer|footnote|foot|sidebar|sponsor|ad[-_ ]|advertisement|popup|overlay|modal|cookie|newsletter|subscribe|share|social|tag|widget|menu|nav|navigation|header|breadcrumb|related|recommended|promo|banner|carousel|slider|skip|sr-only|hidden/i;
  const CONTENT_PATTERN =
    /article|body|content|entry|hentry|main|page|post|text|blog|story|prose|summary|section/i;
  const BLOCK_TAGS = new Set([
    "p",
    "div",
    "article",
    "section",
    "main",
    "td",
    "li",
    "blockquote",
    "pre",
    "h1",
    "h2",
    "h3",
    "h4",
    "h5",
    "h6",
  ]);

  function getTextLength(el) {
    return (el.textContent || "").trim().length;
  }

  function getLinkDensity(el) {
    const text = getTextLength(el);
    if (!text) return 0;
    let linkLen = 0;
    el.querySelectorAll("a").forEach((a) => {
      linkLen += getTextLength(a);
    });
    return linkLen / text;
  }

  function isNoisy(el) {
    const id = (el.id || "").toLowerCase();
    const cls =
      el.className && typeof el.className === "string"
        ? el.className.toLowerCase()
        : "";
    return NOISE_PATTERN.test(id) || NOISE_PATTERN.test(cls);
  }

  function isContenty(el) {
    const id = (el.id || "").toLowerCase();
    const cls =
      el.className && typeof el.className === "string"
        ? el.className.toLowerCase()
        : "";
    return CONTENT_PATTERN.test(id) || CONTENT_PATTERN.test(cls);
  }

  function scoreElement(el) {
    if (NOISE_TAGS.has(el.tagName.toLowerCase())) return -Infinity;
    if (isNoisy(el)) return -100;

    let score = 0;
    const tag = el.tagName.toLowerCase();

    // Use BLOCK_TAGS to confirm this is a meaningful content container
    if (!BLOCK_TAGS.has(tag)) return -50;

    // Tag-specific bonuses
    if (tag === "article" || tag === "main") score += 40;
    else if (tag === "section") score += 20;
    else if (tag === "div") score += 5;
    else if (["p", "blockquote", "pre"].includes(tag)) score += 15;
    else if (["h1", "h2", "h3"].includes(tag)) score += 8;
    else if (tag === "td") score += 3;
    else if (tag === "li") score += 2;

    if (isContenty(el)) score += 25;

    const textLen = getTextLength(el);
    score += Math.min(textLen / 10, 50);

    const commas = ((el.textContent || "").match(/,/g) || []).length;
    score += Math.min(commas * 2, 20);

    score -= getLinkDensity(el) * 50;

    if (textLen < 80) score -= 20;

    return score;
  }

  function extractContent(doc) {
    doc = doc || document;

    const semantic = doc.querySelector("article, [role='main'], main");
    if (semantic && getTextLength(semantic) > 200) {
      return cleanText(semantic.textContent);
    }

    const candidates = Array.from(
      doc.querySelectorAll("div, section, article, td, main"),
    ).filter((el) => {
      if (NOISE_TAGS.has(el.tagName.toLowerCase())) return false;
      if (isNoisy(el)) return false;
      return getTextLength(el) > 80;
    });

    if (!candidates.length) {
      return cleanText(doc.body ? doc.body.textContent : "");
    }

    let best = null,
      bestScore = -Infinity;
    candidates.forEach((el) => {
      const s = scoreElement(el);
      if (s > bestScore) {
        bestScore = s;
        best = el;
      }
    });

    return best ? cleanText(best.textContent) : cleanText(doc.body.textContent);
  }

  function cleanText(raw) {
    return (raw || "")
      .replace(/[\u200b\u200c\u200d\ufeff]/g, "")
      .replace(/[ \t]+/g, " ")
      .replace(/\n{3,}/g, "\n\n")
      .trim();
  }

  function extractTitle(doc) {
    doc = doc || document;
    return (
      doc.querySelector('meta[property="og:title"]')?.getAttribute("content") ||
      doc
        .querySelector('meta[name="twitter:title"]')
        ?.getAttribute("content") ||
      doc.querySelector("h1")?.textContent?.trim() ||
      doc.title ||
      ""
    ).trim();
  }

  global.PageLensReadability = { extractContent, extractTitle, cleanText };
})(typeof window !== "undefined" ? window : globalThis);
